using System;
using System.IO;
using System.Net;
using System.Text;
using System.Diagnostics;
using System.Threading;
using System.Drawing;
using System.Windows.Forms;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
[assembly:System.Reflection.AssemblyTitle("GameDesignerWorkerSpace")]
[assembly:System.Reflection.AssemblyVersion("1.7.1.0")]
class Program {
 public static string Root=AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar);
 public static string Key {get{using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Root.ToLowerInvariant()))).Replace("-","").Substring(0,24);}}
 public static void OpenPage(){try{Process.Start(new ProcessStartInfo("http://127.0.0.1:4173/"){UseShellExecute=true});}catch(Exception e){MessageBox.Show("浏览器未能自动打开，请访问 http://127.0.0.1:4173/\n"+e.Message,"GameDesignerWorkerSpace");}}
 public static bool OpenOtherRunningInstance(){try{using(var client=new ShortWebClient()){var serializer=new JavaScriptSerializer(){MaxJsonLength=50*1024*1024};var health=serializer.DeserializeObject(client.DownloadString("http://127.0.0.1:4173/api/health")) as System.Collections.Generic.Dictionary<string,object>;if(health==null||!health.ContainsKey("app")||(string)health["app"]!="GameDesignerWorkerSpace"||!health.ContainsKey("root")||String.Equals(Path.GetFullPath((string)health["root"]),Path.Combine(Root,"App"),StringComparison.OrdinalIgnoreCase))return false;
   if(MessageBox.Show("另一个位置的工作台正在运行。\n点击确定打开当前运行的项目库；本目录的新版本会在旧服务退出后生效。\n项目文件不会被覆盖。","检测到运行中的工作台",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)==DialogResult.OK){
    string index=Path.Combine(Root,"Data","library.json");if(!File.Exists(index)){try{var workspace=serializer.DeserializeObject(client.DownloadString("http://127.0.0.1:4173/api/workspace")) as System.Collections.Generic.Dictionary<string,object>;var state=workspace["state"] as System.Collections.Generic.Dictionary<string,object>;var infos=workspace["projectInfo"] as System.Collections.Generic.Dictionary<string,object>;var items=new System.Collections.Generic.List<object>();foreach(var value in (object[])state["projects"]){var item=value as System.Collections.Generic.Dictionary<string,object>;string id=(string)item["id"];if(!System.Text.RegularExpressions.Regex.IsMatch(id,"^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$")||!infos.ContainsKey(id))continue;var info=infos[id] as System.Collections.Generic.Dictionary<string,object>;string folder=(string)info["directory"];if(Path.IsPathRooted(folder)&&File.Exists(Path.Combine(folder,"project.json")))items.Add(new {id=id,name=(string)item["name"],directory=folder});}File.WriteAllText(index,serializer.Serialize(new {version=1,projects=items,hiddenLegacy=new string[0]}),new UTF8Encoding(false));}catch{}}
    OpenPage();
   }return true;
  }}catch{return false;}}
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Directory.CreateDirectory(Path.Combine(Root,"Data"));Directory.CreateDirectory(Path.Combine(Root,"Logs"));string node=Path.Combine(Root,"Runtime","node","node.exe");if(!File.Exists(node)){MessageBox.Show("缺少内置运行时，请重新运行安装包。\n"+node,"GameDesignerWorkerSpace");return 1;}
  if(args.Length>0&&args[0]=="--self-test"){string report=args.Length>1?args[1]:Path.Combine(Root,"Logs","self-test.json");var psi=Info(node,"\""+Path.Combine(Root,"App","desktop-self-test.mjs")+"\" \""+report+"\"");using(var p=Process.Start(psi)){p.WaitForExit();return p.ExitCode;}}
  if(OpenOtherRunningInstance())return 0;bool created;using(var mutex=new Mutex(true,"Local\\GDWS-"+Key,out created)){if(!created){OpenPage();return 0;}Application.Run(new WorkbenchContext(node));mutex.ReleaseMutex();}return 0;
 }catch(Exception e){MessageBox.Show("工作台启动失败："+e.Message,"GameDesignerWorkerSpace",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 public static ProcessStartInfo Info(string node,string args){var info=new ProcessStartInfo(node,args){WorkingDirectory=Path.Combine(Root,"App"),UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};info.EnvironmentVariables["GDWS_HOME"]=Root;info.EnvironmentVariables["GDWS_DATA_DIR"]=Path.Combine(Root,"Data");string projects=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"GameDesignerWorkerSpace","Project");string settings=Path.Combine(Root,"Data","settings.json");if(File.Exists(settings)){var data=new JavaScriptSerializer().DeserializeObject(File.ReadAllText(settings)) as System.Collections.Generic.Dictionary<string,object>;if(data!=null&&data.ContainsKey("projectsDirectory"))projects=Path.GetFullPath((string)data["projectsDirectory"]);}info.EnvironmentVariables["GDWS_PROJECTS_DIR"]=projects;return info;}
}
class ShortWebClient:WebClient {protected override WebRequest GetWebRequest(Uri address){var request=base.GetWebRequest(address);request.Timeout=2000;return request;}}
class WorkbenchContext:ApplicationContext {
 NotifyIcon tray;Process service;string log;object gate=new object();bool quitting=false;
 public WorkbenchContext(string node){log=Path.Combine(Program.Root,"Logs","workbench-"+DateTime.Now.ToString("yyyyMMdd")+".log");tray=new NotifyIcon();tray.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);tray.Text="GameDesignerWorkerSpace";var menu=new ContextMenuStrip();menu.Items.Add("打开项目库",null,(s,e)=>Program.OpenPage());menu.Items.Add("检查工作台更新",null,(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(Program.Root,"App","Tools","Updater.exe"),"--root \""+Program.Root+"\""){UseShellExecute=true}));menu.Items.Add("打开日志文件夹",null,(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(Program.Root,"Logs")){UseShellExecute=true}));menu.Items.Add(new ToolStripSeparator());menu.Items.Add("退出工作台服务",null,(s,e)=>Quit());tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>Program.OpenPage();tray.Visible=true;
  var info=Program.Info(node,"\""+Path.Combine(Program.Root,"App","launcher.mjs")+"\"");info.RedirectStandardOutput=true;info.RedirectStandardError=true;service=new Process(){StartInfo=info,EnableRaisingEvents=true};service.OutputDataReceived+=(s,e)=>Write(e.Data);service.ErrorDataReceived+=(s,e)=>Write(e.Data);service.Exited+=(s,e)=>{if(!quitting&&service.ExitCode!=0){Write("Service exited: "+service.ExitCode);MessageBox.Show("工作台服务未能启动。请先关闭其他目录的旧工作台，再重试。\n详情见："+log,"GameDesignerWorkerSpace",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};service.Start();service.BeginOutputReadLine();service.BeginErrorReadLine();
 }
 void Write(string text){if(text==null)return;lock(gate){try{File.AppendAllText(log,DateTime.Now.ToString("HH:mm:ss")+" "+text+Environment.NewLine,Encoding.UTF8);}catch{}}}
 void Quit(){if(MessageBox.Show("请确认网页中的内容已保存。退出后网页将暂时无法读取项目。\n是否退出服务？","退出工作台",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;quitting=true;try{if(service!=null&&!service.HasExited){service.Kill();service.WaitForExit(5000);}else{using(var client=new WebClient()){var data=new JavaScriptSerializer().DeserializeObject(client.DownloadString("http://127.0.0.1:4173/api/health")) as System.Collections.Generic.Dictionary<string,object>;if(data!=null&&data.ContainsKey("root")&&String.Equals(Path.GetFullPath((string)data["root"]),Path.Combine(Program.Root,"App"),StringComparison.OrdinalIgnoreCase)&&data.ContainsKey("pid")){var p=Process.GetProcessById(Convert.ToInt32(data["pid"]));if(p.ProcessName=="node")p.Kill();}}}}catch(Exception e){Write(e.Message);}tray.Visible=false;tray.Dispose();ExitThread();}
}
